import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        String[] g = new String[n];
        for (int i = 0; i < n; i++) g[i] = next();
        long answer = 0;
        for (int i = 0; i < (n + 1) / 2; i++)
            for (int j = 0; j < (m + 1) / 2; j++) {
                // the cell and its mirror images must end up the same color
                int[][] all = {{i, j}, {n - 1 - i, j}, {i, m - 1 - j}, {n - 1 - i, m - 1 - j}};
                Set<Integer> cells = new HashSet<>();
                for (int[] c : all) cells.add(c[0] * m + c[1]);
                int black = 0;
                for (int c : cells) if (g[c / m].charAt(c % m) == 'B') black++;
                answer += Math.min(black, cells.size() - black);
            }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	g := make([]string, n)
	for i := range g {
		sc.Scan()
		g[i] = sc.Text()
	}
	answer := 0
	for i := 0; i < (n+1)/2; i++ {
		for j := 0; j < (m+1)/2; j++ {
			// the cell and its mirror images must end up the same color
			cells := map[[2]int]bool{{i, j}: true, {n - 1 - i, j}: true, {i, m - 1 - j}: true, {n - 1 - i, m - 1 - j}: true}
			black := 0
			for c := range cells {
				if g[c[0]][c[1]] == 'B' {
					black++
				}
			}
			answer += min(black, len(cells)-black)
		}
	}
	fmt.Println(answer)
}
